/// The settings key used to track rebuild progress and recovery state.
pub const REBUILD_STATE_KEY: &str = "rebuild.state";

/// Why a rebuild operation could not complete.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum RebuildError {
    /// A database operation failed.
    #[error(transparent)]
    Db(#[from] DbError),
    /// A SQL error occurred during rebuild.
    #[error("sqlite error: {0}")]
    Sqlite(#[from] rusqlite::Error),
    /// An invariant check failed during or after insertion.
    #[error("rebuild invariant violated: {0}")]
    Invariant(String),
    /// A filesystem I/O error occurred during scanning.
    #[error("io error during rebuild scan: {0}")]
    Io(#[from] io::Error),
    /// JSON parsing failed.
    #[error("json error: {0}")]
    Json(#[from] serde_json::Error),
    /// The rebuild operation was cancelled by the observer.
    #[error("rebuild was cancelled")]
    Cancelled,
}

/// Status of the rebuild job stored in `settings`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RebuildStatus {
    /// Rebuild is idle or not currently active.
    Idle,
    /// Rebuild is currently in progress.
    Running,
    /// Rebuild finished successfully.
    Completed,
    /// Rebuild failed with an error.
    Failed,
}

/// Stored payload for the `rebuild.state` settings entry.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RebuildState {
    /// Current job status.
    pub status: RebuildStatus,
    /// Timestamp when rebuild started (RFC 3339 text).
    pub started_at: String,
    /// Timestamp when rebuild last updated (RFC 3339 text).
    pub updated_at: String,
    /// Current stage name.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stage: Option<String>,
    /// Error description if status is `Failed`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

/// Progress event emitted during rebuild.
#[derive(Debug, Clone, PartialEq)]
pub struct RebuildProgress {
    /// Estimated progress fraction from 0.0 to 1.0.
    pub fraction: f32,
    /// Identifier of the current stage.
    pub stage: &'static str,
    /// Human-readable message.
    pub message: String,
}

/// Callback / observer trait for progress reporting and cancellation.
pub trait RebuildObserver: Send + Sync {
    /// Called when progress is made.
    fn on_progress(&self, progress: RebuildProgress);
    /// Returns true if the operation should abort and rollback.
    fn is_cancelled(&self) -> bool {
        false
    }
}

/// A no-op observer that ignores progress events and never cancels.
#[derive(Debug, Default, Clone, Copy)]
pub struct NoopObserver;

impl RebuildObserver for NoopObserver {
    fn on_progress(&self, _progress: RebuildProgress) {}
}

impl<F> RebuildObserver for F
where
    F: Fn(RebuildProgress) + Send + Sync,
{
    fn on_progress(&self, progress: RebuildProgress) {
        (self)(progress);
    }
}

