fn add_path(
    input: &mut RebuildInput,
    agent_id: &AgentId,
    scope: Scope,
    kind: &str,
    path: &Path,
    format: Option<&str>,
    is_primary: bool,
) {
    let exists = path.exists();
    input.agent_paths.push(DiscoveredAgentPath {
        agent_id: agent_id.clone(),
        scope,
        kind: kind.to_string(),
        path: path.to_string_lossy().to_string(),
        format: format.map(ToString::to_string),
        is_primary,
        exists,
        verified: exists,
    });
}

fn scan_native_and_deployments(
    home: &Path,
    projects: &[(PathBuf, PathBuf)],
    input: &mut RebuildInput,
) {
    // Collect skill directory candidates per agent
    let mut skill_dirs = vec![
        (
            AgentId::ClaudeCode,
            Scope::User,
            None,
            home.join(".claude/skills"),
        ),
        (
            AgentId::Codex,
            Scope::User,
            None,
            home.join(".agents/skills"),
        ),
        (
            AgentId::Omp,
            Scope::User,
            None,
            home.join(".omp/agent/skills"),
        ),
        (
            AgentId::Cursor,
            Scope::User,
            None,
            home.join(".cursor/skills"),
        ),
    ];
    for (proj, _) in projects {
        let proj_id = input
            .projects
            .iter()
            .find(|p| p.path == proj.to_string_lossy().as_ref())
            .map(|p| p.id.clone());

        skill_dirs.push((
            AgentId::ClaudeCode,
            Scope::Project,
            proj_id.clone(),
            proj.join(".claude/skills"),
        ));
        skill_dirs.push((
            AgentId::Codex,
            Scope::Project,
            proj_id.clone(),
            proj.join(".agents/skills"),
        ));
        skill_dirs.push((
            AgentId::Omp,
            Scope::Project,
            proj_id.clone(),
            proj.join(".omp/agent/skills"),
        ));
        skill_dirs.push((
            AgentId::Cursor,
            Scope::Project,
            proj_id,
            proj.join(".cursor/skills"),
        ));
    }

    for (agent, scope, proj_id, sdir) in skill_dirs {
        if !sdir.exists() || !sdir.is_dir() {
            continue;
        }

        if let Ok(entries) = fs::read_dir(&sdir) {
            for entry in entries.flatten() {
                let path = entry.path();
                let name = path
                    .file_name()
                    .unwrap_or_default()
                    .to_string_lossy()
                    .to_string();

                // Check if entry is a symlink
                let is_symlink = path.is_symlink();
                if is_symlink && let Ok(target) = fs::read_link(&path) {
                    let target_canon = fs::canonicalize(&path).unwrap_or_else(|_| target.clone());
                    let target_str = target_canon.to_string_lossy().to_string();

                    // Try to find matching item in input.items
                    let matched_item = input.items.iter().find(|it| {
                        it.source_path
                            .as_deref()
                            .is_some_and(|sp| target_str.ends_with(sp) || sp.ends_with(&name))
                            || it.slug == name
                    });

                    if let Some(item) = matched_item {
                        let store_hash = item.content_hash.clone();
                        input.deployments.push(DiscoveredDeployment {
                            item_id: item.id,
                            agent_id: agent.clone(),
                            scope,
                            project_id: proj_id.clone(),
                            state: ItemState::Linked,
                            mode: Some("symlink".to_string()),
                            target_path: Some(path.to_string_lossy().to_string()),
                            link_target: Some(target.to_string_lossy().to_string()),
                            store_hash: store_hash.clone(),
                            target_hash: store_hash,
                            baseline_hash: item.content_hash.clone(),
                            sync_label: Some(SyncLabel::InSync),
                            operation_id: None,
                        });
                        continue;
                    }
                }
                // If not matched to an item or not a symlink, it is a native item
                let hash = if path.is_dir() {
                    hash_directory_tree(&path).ok()
                } else {
                    fs::read(&path).ok().map(|b| sha256_hex(&b))
                };

                let nat_id = format!("nat_{}", Ulid::generate());
                input.native_items.push(DiscoveredNativeItem {
                    id: nat_id,
                    agent_id: agent.clone(),
                    scope,
                    kind: ItemKind::Skill,
                    name,
                    path: path.to_string_lossy().to_string(),
                    content_hash: hash,
                    status: "new".to_string(),
                    adopted_item_id: None,
                });
            }
        }
    }
}

/// Hashes all files in a directory tree deterministically.
fn hash_directory_tree(dir: &Path) -> io::Result<String> {
    let mut files = Vec::new();
    collect_files_recursive(dir, dir, &mut files)?;
    files.sort_by(|a, b| a.0.cmp(&b.0));

    let mut hasher = Sha256::new();
    for (rel_path, bytes) in files {
        hasher.update(rel_path.as_bytes());
        hasher.update([0]);
        hasher.update(&bytes);
        hasher.update([0]);
    }
    let digest = hasher.finalize();
    let mut out = String::with_capacity(64);
    for byte in digest {
        let _ = write!(out, "{byte:02x}");
    }
    Ok(out)
}
fn collect_files_recursive(
    root: &Path,
    current: &Path,
    out: &mut Vec<(String, Vec<u8>)>,
) -> io::Result<()> {
    if !current.exists() {
        return Ok(());
    }
    for entry in fs::read_dir(current)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_files_recursive(root, &path, out)?;
        } else if path.is_file() {
            let rel = path
                .strip_prefix(root)
                .map_err(|e| io::Error::other(e.to_string()))?
                .to_string_lossy()
                .to_string();
            let bytes = fs::read(&path)?;
            out.push((rel, bytes));
        }
    }
    Ok(())
}

fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    let mut out = String::with_capacity(64);
    for byte in digest {
        let _ = write!(out, "{byte:02x}");
    }
    out
}

fn current_timestamp() -> String {
    // Current UTC time formatted as RFC 3339 text.
    let now = std::time::SystemTime::now();
    let duration = now
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default();
    let secs = duration.as_secs();
    let millis = duration.subsec_millis();

    // Convert epoch seconds to date-time breakdown
    let days = (secs / 86400) as i64;
    let rem_secs = (secs % 86400) as i64;
    let hours = rem_secs / 3600;
    let mins = (rem_secs % 3600) / 60;
    let s = rem_secs % 60;

    // Civil day from days since 1970-01-01
    let (year, month, day) = civil_from_days(days);
    format!("{year:04}-{month:02}-{day:02}T{hours:02}:{mins:02}:{s:02}.{millis:03}Z")
}

fn civil_from_days(days: i64) -> (i32, u32, u32) {
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u32;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y as i32, m, d)
}

// =========================================================================
// Normalized Dump for Idempotence and Equivalence Assertions
// =========================================================================

/// Normalized projection of all derived tables, ignoring timestamps, sorted deterministically.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct NormalizedDump {
    /// Normalized projects.
    pub projects: Vec<NormalizedProject>,
    /// Normalized agents.
    pub agents: Vec<NormalizedAgent>,
    /// Normalized agent paths.
    pub agent_paths: Vec<NormalizedAgentPath>,
    /// Normalized items.
    pub items: Vec<NormalizedItem>,
    /// Normalized item versions.
    pub item_versions: Vec<NormalizedVersion>,
    /// Normalized native items.
    pub native_items: Vec<NormalizedNativeItem>,
    /// Normalized deployments.
    pub deployments: Vec<NormalizedDeployment>,
    /// Normalized locks.
    pub locks: Vec<NormalizedLock>,
    /// Normalized sources.
    pub sources: Vec<NormalizedSource>,
    /// Normalized presets.
    pub presets: Vec<NormalizedPreset>,
    /// Normalized preset members.
    pub preset_members: Vec<NormalizedPresetMember>,
    /// Normalized secret references.
    pub secret_refs: Vec<NormalizedSecretRef>,
    /// Normalized secret reference uses.
    pub secret_ref_uses: Vec<NormalizedSecretRefUse>,
}

