/// Produces a deterministic normalized dump of all derived tables in `connection`.
///
/// Timestamps (`created_at`, `updated_at`, `last_scanned_at`, `captured_at`, etc.)
/// are excluded so two rebuilds producing the same data match byte-for-byte.
///
/// # Errors
/// Returns [`DbError`] if any query fails.
pub fn normalized_derived_dump(connection: &Connection) -> Result<NormalizedDump, DbError> {
    // Projects
    let mut stmt =
        connection.prepare("SELECT path, name, source_root FROM projects ORDER BY path ASC")?;
    let mut projects = stmt
        .query_map([], |r| {
            Ok(NormalizedProject {
                path: r.get(0)?,
                name: r.get(1)?,
                source_root: r.get(2)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    projects.sort();

    // Agents
    let mut stmt = connection
        .prepare("SELECT id, display_name, managed, installed FROM agents ORDER BY id ASC")?;
    let mut agents = stmt
        .query_map([], |r| {
            Ok(NormalizedAgent {
                id: r.get(0)?,
                display_name: r.get(1)?,
                managed: r.get(2)?,
                installed: r.get(3)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    agents.sort();

    // Agent Paths
    let mut stmt = connection.prepare(
        "SELECT agent_id, scope, kind, path, format, is_primary, \"exists\" FROM agent_paths ORDER BY agent_id, scope, kind, path"
    )?;
    let mut agent_paths = stmt
        .query_map([], |r| {
            Ok(NormalizedAgentPath {
                agent_id: r.get(0)?,
                scope: r.get(1)?,
                kind: r.get(2)?,
                path: r.get(3)?,
                format: r.get(4)?,
                is_primary: r.get(5)?,
                exists: r.get(6)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    agent_paths.sort();

    // Items
    let mut stmt = connection.prepare(
        "SELECT id, kind, scope, project_id, slug, name, source_path, content_hash, state, managed FROM items ORDER BY id ASC"
    )?;
    let mut items = stmt
        .query_map([], |r| {
            Ok(NormalizedItem {
                id: r.get(0)?,
                kind: r.get(1)?,
                scope: r.get(2)?,
                project_id: r.get(3)?,
                slug: r.get(4)?,
                name: r.get(5)?,
                source_path: r.get(6)?,
                content_hash: r.get(7)?,
                state: r.get(8)?,
                managed: r.get(9)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    items.sort();

    // Item Versions
    let mut stmt = connection.prepare(
        "SELECT item_id, scope, content_hash, path, size FROM item_versions ORDER BY item_id, content_hash"
    )?;
    let mut item_versions = stmt
        .query_map([], |r| {
            Ok(NormalizedVersion {
                item_id: r.get(0)?,
                scope: r.get(1)?,
                content_hash: r.get(2)?,
                path: r.get(3)?,
                size: r.get(4)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    item_versions.sort();

    // Native Items
    let mut stmt = connection.prepare(
        "SELECT agent_id, scope, kind, name, path, content_hash, status FROM native_items ORDER BY path ASC"
    )?;
    let mut native_items = stmt
        .query_map([], |r| {
            Ok(NormalizedNativeItem {
                agent_id: r.get(0)?,
                scope: r.get(1)?,
                kind: r.get(2)?,
                name: r.get(3)?,
                path: r.get(4)?,
                content_hash: r.get(5)?,
                status: r.get(6)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    native_items.sort();

    // Deployments
    let mut stmt = connection.prepare(
        "SELECT item_id, agent_id, scope, project_id, state, mode, target_path, store_hash, sync_label FROM deployments ORDER BY item_id, agent_id, scope"
    )?;
    let mut deployments = stmt
        .query_map([], |r| {
            Ok(NormalizedDeployment {
                item_id: r.get(0)?,
                agent_id: r.get(1)?,
                scope: r.get(2)?,
                project_id: r.get(3)?,
                state: r.get(4)?,
                mode: r.get(5)?,
                target_path: r.get(6)?,
                store_hash: r.get(7)?,
                sync_label: r.get(8)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    deployments.sort();

    // Locks
    let mut stmt = connection
        .prepare("SELECT item_id, scope, reason, locked_by FROM locks ORDER BY item_id, scope")?;
    let mut locks = stmt
        .query_map([], |r| {
            Ok(NormalizedLock {
                item_id: r.get(0)?,
                scope: r.get(1)?,
                reason: r.get(2)?,
                locked_by: r.get(3)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    locks.sort();

    // Sources
    let mut stmt =
        connection.prepare("SELECT item_id, kind, url, content_hash FROM sources ORDER BY COALESCE(item_id, ''), kind, url")?;
    let mut sources = stmt
        .query_map([], |r| {
            Ok(NormalizedSource {
                item_id: r.get(0)?,
                kind: r.get(1)?,
                url: r.get(2)?,
                content_hash: r.get(3)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    sources.sort();

    // Presets
    let mut stmt =
        connection.prepare("SELECT id, name, scope, is_builtin FROM presets ORDER BY id ASC")?;
    let mut presets = stmt
        .query_map([], |r| {
            Ok(NormalizedPreset {
                id: r.get(0)?,
                name: r.get(1)?,
                scope: r.get(2)?,
                is_builtin: r.get(3)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    presets.sort();

    // Preset Members
    let mut stmt = connection.prepare(
        "SELECT preset_id, item_id, kind, enabled FROM preset_members ORDER BY preset_id, item_id",
    )?;
    let mut preset_members = stmt
        .query_map([], |r| {
            Ok(NormalizedPresetMember {
                preset_id: r.get(0)?,
                item_id: r.get(1)?,
                kind: r.get(2)?,
                enabled: r.get(3)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    preset_members.sort();

    // Secret Refs
    let mut stmt = connection
        .prepare("SELECT name, keychain_service, account FROM secret_refs ORDER BY name ASC")?;
    let mut secret_refs = stmt
        .query_map([], |r| {
            Ok(NormalizedSecretRef {
                name: r.get(0)?,
                keychain_service: r.get(1)?,
                account: r.get(2)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    secret_refs.sort();

    // Secret Ref Uses
    let mut stmt = connection.prepare(
        "SELECT secret_name, item_id, scope FROM secret_ref_uses ORDER BY secret_name, COALESCE(item_id, ''), COALESCE(scope, '')"
    )?;
    let mut secret_ref_uses = stmt
        .query_map([], |r| {
            Ok(NormalizedSecretRefUse {
                secret_name: r.get(0)?,
                item_id: r.get(1)?,
                scope: r.get(2)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    secret_ref_uses.sort();

    Ok(NormalizedDump {
        projects,
        agents,
        agent_paths,
        items,
        item_versions,
        native_items,
        deployments,
        locks,
        sources,
        presets,
        preset_members,
        secret_refs,
        secret_ref_uses,
    })
}
